mapper.select:
select b.*, d.name database_name
from backup_record b
join database_catalog d on d.id = b.database_id

  b.database_id = #{databaseId}
  and b.backup_date >= #{from}
  and b.backup_date <= #{to}
  and b.kind = #{kind}
  and lower(b.status) = lower(#{status})

order by b.backup_date desc, b.event_time desc, b.id desc
limit #{limit} offset #{offset}

select b.*, d.name database_name
from backup_record b
join database_catalog d on d.id = b.database_id
where b.database_id = #{databaseId}
  and b.kind = #{kind}
  and b.backup_date between #{from} and #{to}
order by b.backup_date, b.event_time, b.id

select ranked.id, ranked.database_id, ranked.database_name, ranked.kind, ranked.external_id, ranked.backup_date, ranked.date_inferred, ranked.event_time, ranked.status from ( select b.id, b.database_id, d.name database_name, b.kind, b.external_id, b.backup_date, b.date_inferred, b.event_time, b.status, row_number() over (partition by b.database_id order by b.backup_date desc, b.event_time desc, b.id desc) rank_no from backup_record b join database_catalog d on d.id = b.database_id where b.database_id in
#{databaseId}
) ranked where ranked.rank_no = 1

mapper.delete:
delete from backup_record
where kind = #{kind}
  and kind in ('daily', 'monthly')
  and backup_date < #{cutoff}
